presets.css:
/* =========================================================
   Puff · 长夜＆机械之心 × 夜间极简完全体
   （完美居中引用 / 哑光米白底 / 全局白字）
   ========================================================= */

/* 0. 页面纯黑底 */
html, body {
  background: #000000 !important;
}

/* 1. 全局变量与强制方角 */
.off-app {
  --off-list-radius: 0px;
  --off-list-ava-size: 52px;
  --off-glass-border: rgba(255, 255, 255, 0.3);
  --off-glass-shadow: 0 8px 30px rgba(0, 0, 0, 0.8), inset 0 1px 0 rgba(255, 255, 255, 0.1);
}

.off-app .off-list,
.off-app .off-list-ava,
.off-app.off-app-session .off-passage-sheet,
.off-app .off-compose-bar,
.off-inbox-filter,
.off-inbox-filter button,
.off-app .off-thinking-chip {
  border-radius: 0 !important;
}

/* =========================================================
   👇 核心 1：全局文字纯白
   ========================================================= */
.off-app p, .off-app span, .off-app div, 
.off-app h1, .off-app h2, .off-app h3, .off-app h4, .off-app h5, .off-app h6,
.off-app strong, .off-app em, .off-app a, .off-app i,
.off-app [class*="title"], .off-app [class*="text"], .off-app [class*="label"], .off-app [class*="desc"] {
  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;
}

/* 针对日间版留下的“共处”黑字/背景裁切进行强制修正 */
.off-app:not(.off-app-session) .off-stage-head *,
.off-app:not(.off-app-session) .off-title,
.off-app:not(.off-app-session) .off-title * {
  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;
  opacity: 1 !important;
  background: transparent !important;
  -webkit-background-clip: border-box !important;
  background-clip: border-box !important;
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.95) !important;
}

/* =========================================================
   👇 核心 2：单聊 / 群共处（白底无缝占满 + 强行黑字）
   ========================================================= */
.off-inbox-filter {
  background: rgba(0, 0, 0, 0.6) !important;
  border: 1px solid #444 !important;
  backdrop-filter: blur(15px) !important;
  padding: 0 !important; 
  gap: 0 !important;
  display: flex !important;
  overflow: hidden !important;
}

.off-inbox-filter button {
  flex: 1 !important; 
  margin: 0 !important;
  border: none !important;
  border-radius: 0 !important;
  background: transparent !important;
  white-space: nowrap !important;
  padding: 8px 4px !important;
  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;
}

.off-inbox-filter button.on {
  background: #ffffff !important;
}

.off-inbox-filter button.on,
.off-inbox-filter button.on *,
.off-inbox-filter button.on span,
.off-inbox-filter button.on svg {
  color: #000000 !important;
  -webkit-text-fill-color: #000000 !important;
  fill: #000000 !important;
  text-shadow: none !important;
}

/* =========================================================
   2. 背景图源分离：预览透星空，聊天纯黑
   ========================================================= */
.off-app,
.off-app:not(.off-app-session) .off-stage,
.off-app:not(.off-app-session) .off-stage.has-bg {
  background-color: #000000 !important;
  background-image: url('https://picui.ogmua.cn/s1/2026/11/08/6aefd141288ba.webp') !important;
  background-size: cover !important;
  background-position: center !important;
  background-attachment: fixed !important;
}

.off-app.off-app-session,
.off-app.off-app-session .off-stage,
.off-app.off-app-session .off-stage.has-bg {
  background-color: #000000 !important;
  background-image: none !important;
}
.off-app .off-prose-scroll {
  background-color: transparent !important;
}

/* =========================================================
   4. 列表容器玻璃效果
   ========================================================= */
.off-app:not(.off-app-session) .off-list {
  background: rgba(0, 0, 0, 0.75) !important; 
  border: 1px solid var(--off-glass-border) !important;
  backdrop-filter: blur(15px) !important;
  -webkit-backdrop-filter: blur(15px) !important;
  box-shadow: var(--off-glass-shadow) !important;
  overflow: hidden !important;
}
.off-list-btn { 
  border-bottom: 1px solid rgba(255, 255, 255, 0.15) !important; 
  background: transparent !important; 
}
.off-list-body strong { font-weight: 400 !important; }
.off-list-body span { opacity: 0.75 !important; }

/* =========================================================
   5. 聊天顶栏 + 心电图
   ========================================================= */
.off-app.off-app-session .off-stage-head {
  background: #000000 !important; 
  border-bottom: none !important;
  position: relative !important;
  overflow: visible !important;
  z-index: 10 !important;
}

.off-app.off-app-session .off-stage-head::after {
  content: "" !important; position: absolute !important; bottom: -16px !important; left: 0 !important; right: 0 !important; height: 16px !important;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 20" preserveAspectRatio="none"><path d="M0 15 L10 15 L15 15 L18 5 L22 18 L25 10 L28 15 L40 15 L43 12 L46 15 L60 15 L63 5 L67 18 L70 10 L73 15 L85 15 L88 12 L91 15 L100 15" fill="none" stroke="%23ffffff" stroke-width="1.5" opacity="0.8"/></svg>') !important;
  background-size: 120px 16px !important; background-repeat: repeat-x !important;
  animation: ecg-flow 3s linear infinite !important; z-index: 99 !important;
}
.off-app.off-app-session .off-stage-head::before {
  content: '♥' !important; position: absolute !important; bottom: -23px !important; left: 10% !important; font-size: 16px !important;
  text-shadow: 0 0 8px rgba(255, 255, 255, 0.9) !important; 
  z-index: 999 !important; pointer-events: none !important;
  animation: heart-walk 4s ease-in-out infinite alternate !important;
}

/* =========================================================
   6. 聊天消息卡片
   ========================================================= */
.off-app.off-app-session {
  --off-card-user: #000000;
  --off-card-peer: #000000;
  --off-card-border: #333333;
}
.off-app.off-app-session .off-passage-sheet {
  background: var(--off-card-peer) !important;
  border: 1px solid var(--off-card-border) !important;
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.9) !important;
}
.off-app.off-app-session .off-passage.is-me .off-passage-sheet {
  background: var(--off-card-user) !important;
  border-color: #555555 !important; 
}

/* 正文行高恢复自然 */
.off-app.off-app-session .off-prose-para,
.off-app.off-app-session .off-prose-narr,
.off-app.off-app-session .off-prose-plain {
  line-height: 1.85 !important; 
  font-size: 14.5px !important;
}

/* =========================================================
   👇 核心 3：极简反白引用（上下绝对居中，哑光白底）
   ========================================================= */
.off-app.off-app-session .off-prose-dial,
.off-app.off-app-session [class*="dial"],
.off-app .off-compose-quote,
.off-app .off-passage-quote,
.off-app [class*="quote"] {
  background: #f2f2f7 !important; /* 哑光米白，不刺眼 */
  border: none !important; 
  border-radius: 2px !important; 

  /* 核心微调：上下各 1px 的 padding 让背景完美包覆文字，不再头重脚轻 */
  padding: 1px 4px !important; 
  margin: 0 !important; 

  box-shadow: none !important; 
  backdrop-filter: none !important; 
  -webkit-box-decoration-break: clone !important;
  box-decoration-break: clone !important;

  /* 移除所有位置偏移，回归自然基线 */
  position: static !important;

  /* 父级锁定黑字 */
  color: #000000 !important;
  -webkit-text-fill-color: #000000 !important;
}

/* 暴力穿透：强制引用框内所有子孙元素全部变黑 */
.off-app.off-app-session .off-prose-dial *,
.off-app.off-app-session [class*="dial"] *,
.off-app .off-compose-quote *,
.off-app .off-passage-quote *,
.off-app [class*="quote"] * {
  color: #000000 !important; 
  -webkit-text-fill-color: #000000 !important;
  -webkit-text-stroke: 0 transparent !important;
  background: transparent !important;
  text-shadow: none !important; 
  font-family: "Noto Serif SC", "Songti SC", serif !important; 
}


/* =========================================================
   7. 长按悬浮菜单
   ========================================================= */
.off-app [class*="menu"], .off-app [class*="popover"], .off-app [class*="popup"], .off-app [class*="dialog"], .off-app [class*="action"] {
  background: rgba(10, 10, 10, 0.95) !important;
  backdrop-filter: blur(24px) !important;
  border: 1px solid rgba(255, 255, 255, 0.3) !important;
  border-radius: 8px !important;
  box-shadow: 0 12px 36px rgba(0, 0, 0, 0.9), 0 0 15px rgba(255, 255, 255, 0.05) !important;
}
.off-app [class*="menu"] *, .off-app [class*="popover"] *, .off-app [class*="popup"] * { background: transparent !important; }
.off-app [class*="menu"] [class*="preview"], .off-app [class*="menu"] [class*="text"], .off-app [class*="menu"] [class*="content"] {
  color: #cccccc !important; -webkit-text-fill-color: #cccccc !important; font-family: "Songti SC", serif !important; border-bottom: 1px dashed rgba(255, 255, 255, 0.2) !important;
}
.off-app [class*="menu"] button, .off-app [class*="menu"] span, .off-app [class*="menu"] svg { color: #ffffff !important; -webkit-text-fill-color: #ffffff !important; fill: #ffffff !important; }
.off-app [class*="delete"] *, .off-app [class*="danger"] * { 
  color: #ff5555 !important; 
  -webkit-text-fill-color: #ff5555 !important; 
  fill: #ff5555 !important; 
}

/* =========================================================
   8. 底栏 + 发送框
   ========================================================= */
.off-app.off-app-session .off-stage-dock {
  background: #000000 !important; 
  border-top: none !important; position: relative !important; overflow: visible !important; z-index: 10 !important;
  padding-top: 20px !important; padding-bottom: 20px !important; 
}
.off-app.off-app-session .off-stage-dock::before {
  content: "" !important; position: absolute !important; top: -16px !important; left: 0 !important; right: 0 !important; height: 16px !important;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 20" preserveAspectRatio="none"><path d="M0 15 L10 15 L15 15 L18 5 L22 18 L25 10 L28 15 L40 15 L43 12 L46 15 L60 15 L63 5 L67 18 L70 10 L73 15 L85 15 L88 12 L91 15 L100 15" fill="none" stroke="%23ffffff" stroke-width="1.5" opacity="0.8"/></svg>') !important;
  background-size: 120px 16px !important; background-repeat: repeat-x !important;
  animation: ecg-flow-reverse 3s linear infinite !important; z-index: 99 !important;
}

.off-app .off-compose-bar {
  background: #000000 !important;
  border: 1px solid #333 !important;
  box-shadow: 0 5px 20px rgba(0, 0, 0, 0.8) !important;
}
.off-app .off-compose-input::placeholder { 
  color: #666 !important; 
  -webkit-text-fill-color: #666 !important; 
}

/* 发送图标强制纯白 */
.off-app .off-compose-send, 
.off-app .off-compose-send *,
.off-app .off-compose-send i,
.off-app .off-compose-send svg {
  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;
  fill: #ffffff !important;
  background: transparent !important;
}

/* =========================================================
   9. 头像（方框白边微光）
   ========================================================= */
.off-app .off-list-ava,
.off-app .chat-ava-list {
  border-radius: 0 !important; border: 1px solid #777 !important; 
  background: #111111 !important; padding: 2px !important;
  box-shadow: inset 0 0 4px rgba(255, 255, 255, 0.1), 0 0 8px rgba(255, 255, 255, 0.1) !important; 
  animation: white-glow 3s ease-in-out infinite alternate !important; 
}
.off-app .off-list-ava img,
.off-app .chat-ava-list img {
  border-radius: 0 !important; object-fit: cover !important;
}

/* 动画 */
@keyframes ecg-flow { 0% { background-position: 0 0; } 100% { background-position: -120px 0; } }
@keyframes ecg-flow-reverse { 0% { background-position: 0 0; } 100% { background-position: 120px 0; } }
@keyframes heart-walk {
  0% { left: 4%; transform: translateY(0) scale(1); } 30% { transform: translateY(-4px) scale(1.15); } 
  60% { transform: translateY(0) scale(1); } 80% { transform: translateY(-4px) scale(1.15); } 
  100% { left: 96%; transform: translateY(0) scale(1); }
}
@keyframes white-glow {
  0% { box-shadow: inset 0 0 4px rgba(255, 255, 255, 0.1), 0 0 2px rgba(255, 255, 255, 0.1); }
  100% { box-shadow: inset 0 0 6px rgba(255, 255, 255, 0.2), 0 0 10px rgba(255, 255, 255, 0.3); }
}
